ALTER TABLE "shop_variants" ADD COLUMN "pushed_weight_grams" integer;--> statement-breakpoint
-- Versandgewicht wie bei Delta Pro (Wunsch Inhaber 19.11.2026: „الأوزان … زي ما موجود في دلتا برو بالظبط“, verbunden über den
-- Barcode wie im System). Quelle: deltaprosupply.com, gleicher EAN – „Package weight“ bzw. Gewicht der Shop-Variante, in Gramm.
-- Offensichtliche Fehler dort (Versandgewicht > 3 × Produktgewicht + 2 kg, z. B. 879 kg statt 87,9 kg) sind nicht dabei.
-- Vorher-Stand im audit_log. pushed_weight_grams ist überall leer → der Worker meldet die Gewichte an beide Shops (pushDueWeights).
