), old AS (
  SELECT v.id, v.weight_grams AS before, d.grams AS after
  FROM variants v JOIN d ON v.barcode = d.code
  WHERE v.weight_grams IS DISTINCT FROM d.grams
), upd AS (
  UPDATE variants v SET weight_grams = o.after, updated_at = now() FROM old o WHERE v.id = o.id RETURNING v.id
)
INSERT INTO audit_log (id, entity, entity_id, action, before, after, user_id)
SELECT gen_random_uuid()::text, 'variant', o.id, 'weight', jsonb_build_object('weightGrams', o.before),
       jsonb_build_object('weightGrams', o.after, 'reason', 'Delta Pro'), NULL
FROM old o JOIN upd u ON u.id = o.id;
